content:
:root {
  --primary-color: #ff6b6b;
  --primary-hover: #fa5252;
  --secondary-color: #4dabf7;
  --secondary-hover: #339af0;
  --bg-gradient: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  --card-bg: #ffffff;
  --text-color: #333333;
  --text-light: #666666;
  --border-radius: 16px;
  --box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

*:focus-visible {
  outline: 3px solid var(--secondary-color);
  outline-offset: 2px;
}

body {
  background: var(--bg-gradient);
  color: var(--text-color);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  width: 100%;
  max-width: 480px;
}

.timer-card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--box-shadow);
  padding: 30px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.mode-selector {
  display: flex;
  background: #f1f3f5;
  border-radius: 30px;
  padding: 4px;
  margin-bottom: 24px;
  width: 100%;
  max-width: 280px;
}

.mode-btn {
  flex: 1;
  background: transparent;
  border: none;
  border-radius: 26px;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-light);
  cursor: pointer;
  transition: all 0.2s ease;
}

.mode-btn.active {
  background: var(--card-bg);
  color: var(--text-color);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.status-text {
  font-size: 16px;
  font-weight: 500;
  color: var(--text-light);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.timer-display {
  font-size: 4rem;
  font-weight: 700;
  color: var(--text-color);
  margin: 10px 0 30px 0;
  font-variant-numeric: tabular-nums;
  letter-spacing: -2px;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.btn {
  border: none;
  border-radius: 12px;
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.2s ease;
  flex: 1;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: #f1f3f5;
  color: var(--text-color);
}

.btn-secondary:hover {
  background-color: #e9ecef;
}

@media (max-width: 480px) {
  .timer-card {
    padding: 20px;
  }

  .timer-display {
    font-size: 3.5rem;
  }
}

@media (max-width: 320px) {
  .app-container {
    padding: 10px;
  }

  .timer-card {
    padding: 15px;
  }

  .timer-display {
    font-size: 2.8rem;
    margin: 5px 0 20px 0;
  }

  .btn {
    padding: 10px 12px;
    font-size: 14px;
  }

  .mode-btn {
    font-size: 12px;
    padding: 6px 10px;
  }
}

export type TimerMode = 'work' | 'break';

export interface TimerState {
  timeLeft: number;
  isRunning: boolean;
  mode: TimerMode;
}

export interface TimerSettings {
  workDuration: number;
  breakDuration: number;
  longBreakDuration?: number;
  autoStartBreaks?: boolean;
  autoStartPomodoros?: boolean;
}

export interface TimerHistoryRecord {
  id: string;
  mode: TimerMode;
  duration: number;
  timestamp: Date;
}

import { FC } from 'react';

interface TimerDisplayProps {
  timeLeft: number;
}

export const TimerDisplay: FC<TimerDisplayProps> = ({ timeLeft }) => {
  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;

  const formattedTime = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  // プログレスバー用の計算（標準的な作業時間25分を基準とする）
  const maxTime = 25 * 60;
  const progress = Math.min(100, Math.max(0, (timeLeft / maxTime) * 100));

  return (
    <div style={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <div 
        className="timer-display"
        aria-live="polite"
        aria-label={`残り時間 ${formattedTime}`}
      >
        {formattedTime}
      </div>
      <div style={{ width: '100%', height: '6px', background: '#e9ecef', borderRadius: '3px', overflow: 'hidden', marginBottom: '20px' }}>
        <div 
          style={{ 
            width: `${progress}%`, 
            height: '100%', 
            background: 'var(--primary-color)', 
            transition: 'width 1s linear' 
          }} 
        />
      </div>
    </div>
  );
};

export default TimerDisplay;

import { FC, useEffect } from 'react';

interface ControlPanelProps {
  isRunning: boolean;
  onStart: () => void;
  onPause: () => void;
  onReset: () => void;
}

export const ControlPanel: FC<ControlPanelProps> = ({
  isRunning,
  onStart,
  onPause,
  onReset,
}) => {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' && e.target === document.body) {
        e.preventDefault();
        if (isRunning) {
          onPause();
        } else {
          onStart();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isRunning, onStart, onPause]);

  return (
    <div className="controls">
      {isRunning ? (
        <button 
          className="btn btn-secondary" 
          onClick={onPause}
          aria-label="タイマーを一時停止する"
        >
          一時停止
        </button>
      ) : (
        <button 
          className="btn btn-primary" 
          onClick={onStart}
          aria-label="タイマーを開始する"
        >
          開始
        </button>
      )}
      <button 
        className="btn btn-secondary" 
        onClick={onReset}
        aria-label="タイマーをリセットする"
      >
        リセット
      </button>
    </div>
  );
};

export default ControlPanel;

import { FC, useState } from 'react';
import { TimerMode } from '../types';

interface ModeSelectorProps {
  currentMode: TimerMode;
  onModeChange: (mode: TimerMode) => void;
}

export const ModeSelector: FC<ModeSelectorProps> = ({
  currentMode,
  onModeChange,
}) => {
  const [isCustomOpen, setIsCustomOpen] = useState(false);
  const [customMinutes, setCustomMinutes] = useState(25);

  return (
    <div style={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
      <div className="mode-selector">
        <button
          className={`mode-btn ${currentMode === 'work' && !isCustomOpen ? 'active' : ''}`}
          onClick={() => {
            setIsCustomOpen(false);
            onModeChange('work');
          }}
          aria-label="作業モード 25分"
        >
          作業 (25分)
        </button>
        <button
          className={`mode-btn ${currentMode === 'break' && !isCustomOpen ? 'active' : ''}`}
          onClick={() => {
            setIsCustomOpen(false);
            onModeChange('break');
          }}
          aria-label="休憩モード 5分"
        >
          休憩 (5分)
        </button>
        <button
          className={`mode-btn ${isCustomOpen ? 'active' : ''}`}
          onClick={() => setIsCustomOpen(!isCustomOpen)}
          aria-label="カスタム時間設定"
        >
          カスタム
        </button>
      </div>

      {isCustomOpen && (
        <div style={{ marginBottom: '16px', display: 'flex', gap: '8px', alignItems: 'center' }}>
          <label style={{ fontSize: '14px', color: 'var(--text-light)' }}>時間(分):</label>
          <input
            type="number"
            min="1"
            max="120"
            value={customMinutes}
            onChange={(e) => setCustomMinutes(Number(e.target.value))}
            style={{ width: '60px', padding: '4px', borderRadius: '4px', border: '1px solid #ced4da' }}
          />
          <button
            className="btn btn-primary"
            style={{ padding: '4px 12px', fontSize: '14px', flex: 'none' }}
            onClick={() => {
              onModeChange('work');
            }}
          >
            適用
          </button>
        </div>
      )}
    </div>
  );
};

export default ModeSelector;

import { useState, useEffect, FC } from 'react';
import { TimerState, TimerMode } from './types';
import TimerDisplay from './components/TimerDisplay';
import ControlPanel from './components/ControlPanel';
import ModeSelector from './components/ModeSelector';
import './index.css';

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

export const App: FC = () => {
  const [state, setState] = useState<TimerState>({
    timeLeft: WORK_TIME,
    isRunning: false,
    mode: 'work',
  });

  const playSound = () => {
    try {
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(440, audioCtx.currentTime);
      gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.5);
    } catch (e) {
      // AudioContext not allowed or supported
    }
  };

  const notifyCompletion = (mode: TimerMode) => {
    if ('Notification' in window) {
      if (Notification.permission === 'granted') {
        new Notification(mode === 'work' ? '集中タイムが終了しました！' : '休憩タイムが終了しました！');
      } else if (Notification.permission !== 'denied') {
        Notification.requestPermission().then((permission) => {
          if (permission === 'granted') {
            new Notification(mode === 'work' ? '集中タイムが終了しました！' : '休憩タイムが終了しました！');
          }
        });
      }
    }
  };

  useEffect(() => {
    let interval: number | undefined;

    if (state.isRunning) {
      const endTime = Date.now() + state.timeLeft * 1000;

      interval = window.setInterval(() => {
        const remaining = Math.round((endTime - Date.now()) / 1000);
        if (remaining <= 0) {
          clearInterval(interval);
          playSound();
          notifyCompletion(state.mode);
          setState((prev) => ({
            ...prev,
            timeLeft: 0,
            isRunning: false,
          }));
        } else {
          setState((prev) => ({
            ...prev,
            timeLeft: remaining,
          }));
        }
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [state.isRunning, state.mode]);

  const handleStart = () => {
    setState((prev) => ({ ...prev, isRunning: true }));
  };

  const handlePause = () => {
    setState((prev) => ({ ...prev, isRunning: false }));
  };

  const handleReset = () => {
    const defaultTime = state.mode === 'work' ? WORK_TIME : BREAK_TIME;
    setState((prev) => ({
      ...prev,
      timeLeft: defaultTime,
      isRunning: false,
    }));
  };

  const handleModeChange = (newMode: TimerMode) => {
    const newTime = newMode === 'work' ? WORK_TIME : BREAK_TIME;
    setState({
      timeLeft: newTime,
      isRunning: false,
      mode: newMode,
    });
  };

  const statusText = state.mode === 'work' ? '集中タイム' : '休憩タイム';

  return (
    <div className="app-container">
      <div className="timer-card">
        <ModeSelector
          currentMode={state.mode}
          onModeChange={handleModeChange}
        />
        <div className="status-text">{statusText}</div>
        <TimerDisplay timeLeft={state.timeLeft} />
        <ControlPanel
          isRunning={state.isRunning}
          onStart={handleStart}
          onPause={handlePause}
          onReset={handleReset}
        />
      </div>
    </div>
  );
};

export default App;
